          '提前停藥可能留下存活的細菌，導致合併症，例如侵犯關節並可能傷及心臟的風濕熱，以及腎臟發炎。這些合併症可能在數週後才出現，並留下後遺症。 出現皮疹、尿液變深或水腫時，應立即評估，以檢查這些合併症。',
