          '用清水與肥皂洗手，尤其在咳嗽、打噴嚏或碰觸共用物品之後，是效果最好的單一措施。搓洗掌心、手背、指縫與指甲下方都有差別。 一般肥皂即可，家庭日常不需要特別的抗菌產品。 沒有洗手台時乾洗手有幫助，但手明顯髒污時不能取代清洗。',
