          '腹瀉是一種防禦：腸道加快蠕動，把病原體與它產生的毒素排出。藥物中止這個動作後，刺激性內容物與黏膜接觸的時間更長，表面上的好轉可能伴隨無聲的惡化。兒童的風險更高，因為水分儲備較少。',
          '真正有效的是從第一次腹瀉就開始補液。原因請見[為什麼不該用藥物止瀉](/artigos/gastroenterite-remedios/)。在任何情況下，口服補液鹽都是基礎。',
