          '水分限制在每天 1.5 至 2 公升，只保留給持續充血、功能分級較差或血鈉偏低的人，實際量由醫療團隊決定。',
          '病情穩定、排尿正常的人不需要在沒有指示的情況下少喝水。沒有適應症而限水，可能讓腎功能變差，也沒有好處。天氣炎熱或發燒時，水分需求會改變，應先詢問團隊。',
