          '把數值記在筆記本或手機裡。三天內增加 2 公斤，即使自覺還好，也應聯絡基層健康中心。不要等浮腫出現才行動：體重計會先給出訊號。',
          '單日數字不能決定什麼，重要的是趨勢。一頓較鹹的晚餐可能讓數字上升，腹瀉則可能讓它下降。記錄本比記憶可靠。',
