        url: 'https://www.msdmanuals.com/pt/casa/problemas-de-sa%C3%BAde-infantil/dist%C3%BArbios-respirat%C3%B3rios-em-beb%C3%AAs-e-crian%C3%A7as/bronquiolite',
        label: '細支氣管炎，家庭健康版',
        publisher: 'MSD 診療手冊',
