          '因此，有明顯纖維化或肝硬化的人通常會接受特定追蹤，定期做影像檢查。目的是在腫瘤還小、治療選擇較多時及早發現。這個時程由團隊訂定，即使沒有症狀也應遵循。',
          '肝癌風險不限於肝硬化的人。有明顯纖維化與代謝因子的人也需要留意，追蹤可能包含定期影像檢查。目的不是製造恐慌，而是在還有治療選擇時及早發現。',
